metrics.workdir_dsl:
workspace "Parcel Tracker" "C4 model of the parcel delivery tracking platform" {

    !identifiers hierarchical

    model {
        properties {
            "structurizr.inspection.docs" "ignore"
            "structurizr.inspection.adrs" "ignore"
            "structurizr.inspection.disconnected" "ignore"
        }

        customer = person "Customer" "Looks up the status of their parcels"
        emailProvider = softwareSystem "Email Delivery Provider" "Sends customer notification emails" "External"

        parcelTracker = softwareSystem "Parcel Tracker" "Parcel delivery tracking platform owned and operated by our company" {
            database = container "Database" "Stores shipments and dispatch records" "Database" "Database"
            webPortal = container "Web Portal" "Where customers look up shipments" "Web application" "Web" {
                pricingLibrary = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
            }
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                pricingLibrary = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
            }
        }

        customer -> parcelTracker.webPortal "looks up the status of their parcels" "HTTPS"
        parcelTracker.webPortal -> parcelTracker.database "reads shipment records from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "reads and writes dispatch records in" "SQL"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        component parcelTracker.webPortal "WebPortalComponents" {
            include *
            autoLayout
            title "Components of Web Portal"
        }

        component parcelTracker.dispatchService "DispatchServiceComponents" {
            include *
            autoLayout
            title "Components of Dispatch Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
